class ParameterHandler:
    """Handles the processing of a vertex's parameters.

    This class extracts the parameter-processing logic out of :class:`Vertex` so that
    it can be tested independently. It is responsible for turning the raw template
    definition of a node, together with the edges connected to the vertex, into a
    dictionary of parameters ready to be used when building the component.
    """

    def __init__(self, vertex: Vertex, storage_service: StorageService) -> None:
        self.vertex = vertex
        self.graph = vertex.graph
        self.storage_service = storage_service
        # Only dict-valued entries in the template are actual field definitions.
        self.template_dict: dict[str, dict] = {
            key: value
            for key, value in vertex.data["node"]["template"].items()
            if isinstance(value, dict)
        }
        self.params: dict = {}
        self.load_from_db_fields: list[str] = []

    def process_edge_parameters(self, edges: list) -> dict:
        """Build the parameters that come from the edges connected to the vertex.

        Iterates over ``edges``, skipping any edge without a ``target_param``, and
        returns a dict mapping each ``target_param`` to the source vertex (or a
        structure derived from it).
        """
        params: dict = {}
        for edge in edges:
            if not hasattr(edge, "target_param") or edge.target_param is None:
                continue
            param_key = edge.target_param

            # If the param_key is in the template_dict and the edge.target_id is the
            # current node we make sure params with the same name but different
            # target_id don't get overwritten.
            if param_key in self.template_dict and edge.target_id == self.vertex.id:
                field = self.template_dict[param_key]
                if field.get("list"):
                    if param_key not in params:
                        params[param_key] = []
                    params[param_key].append(self.graph.get_vertex(edge.source_id))
                else:
                    params[param_key] = self.process_non_list_edge_param(field, edge)
            elif param_key in self.vertex.output_names:
                params[param_key] = self.graph.get_vertex(edge.source_id)
        return params

    def process_non_list_edge_param(self, field: dict, edge: Edge) -> Any:
        """Resolve the value of a non-``list`` field connected through an edge.

        Returns the source vertex for empty or non-dict field values, and a new dict
        mapping the existing key to the source vertex for single-entry dict values.
        """
        param_dict = field.get("value")
        if not isinstance(param_dict, dict) or not param_dict or len(param_dict) != 1:
            return self.graph.get_vertex(edge.source_id)
        return {key: self.graph.get_vertex(edge.source_id) for key in param_dict}

    def should_skip_field(self, field_name: str, field: dict, params: dict) -> bool:
        """Return ``True`` if a field should not be processed as a parameter."""
        if field_name in params or field_name == "_type":
            return True
        return not field.get("show")

    def process_file_field(self, field_name: str, field: dict, params: dict) -> dict:
        """Process a ``file`` field, resolving the full path(s) of the stored file(s)."""
        if file_path := field.get("file_path"):
            try:
                full_path: str | list[str] = ""
                if field.get("list"):
                    full_path = []
                    if isinstance(file_path, str):
                        file_path = [file_path]
                    for p in file_path:
                        flow_id, file_name = os.path.split(p)
                        path = self.storage_service.build_full_path(flow_id, file_name)
                        full_path.append(path)
                else:
                    flow_id, file_name = os.path.split(file_path)
                    full_path = self.storage_service.build_full_path(flow_id, file_name)
            except ValueError as e:
                if "too many values to unpack" in str(e):
                    full_path = file_path
                else:
                    raise
            params[field_name] = full_path
        elif field.get("required"):
            field_display_name = field.get("display_name")
            logger.warning(
                f"File path not found for {field_display_name} in component {self.vertex.display_name}. "
                "Setting to None."
            )
            params[field_name] = None
        elif field.get("list"):
            params[field_name] = []
        else:
            params[field_name] = None
        return params

    def handle_optional_field(self, field_name: str, field: dict, params: dict) -> None:
        """Set the default value of an optional field or remove it if there is none."""
        if not field.get("required") and params.get(field_name) is None:
            if field.get("default"):
                params[field_name] = field.get("default")
            else:
                params.pop(field_name, None)

